package main

import (
	"encoding/base64"
	"log"

	"fyne.io/fyne/v2"
	"github.com/getlantern/systray"
)

func iconData() []byte {
	const iconBase64 = ""
	data, err := base64.StdEncoding.DecodeString(iconBase64)
	if err != nil {
		return nil // 解码失败返回 nil，让系统使用默认图标
	}
	return data
}

func setupSystray(w fyne.Window, a fyne.App) {
	go func() {
		systray.Run(func() {
			iconBytes := iconData()
			if len(iconBytes) == 0 {
				log.Println("systray warning: icon bytes empty, skip icon")
			} else {
				// systray.SetIcon does not always return error in this version, so call directly.
				systray.SetIcon(iconBytes)
			}

			mShow := systray.AddMenuItem("显示窗口", "显示并激活 GoShare 窗口")
			mQuit := systray.AddMenuItem("退出", "退出应用")

			go func() {
				for {
					select {
					case <-mShow.ClickedCh:
						w.Show()
						w.RequestFocus()
					case <-mQuit.ClickedCh:
						w.Close()
						a.Quit()
						systray.Quit()
						return
					}
				}
			}()
		}, func() {
			// onExit
		})
	}()
}
